package com.xdownload.mobile;
import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Persist only individually validated ranges. A checkpoint binds the source, strong ETag, size and segment layout. */
final class ParallelEngine{
 static File meta(File target){return new File(target.getPath()+".ranges");}
 static File segment(File target,int i){return new File(target.getPath()+".range"+i);}
 static boolean hasCheckpoint(File target){return meta(target).isFile();}
 static void clear(File target){meta(target).delete();new File(meta(target).getPath()+".tmp").delete();for(int i=0;i<DynamicRanges.MAX_PARTS;i++)segment(target,i).delete();}
 static long savedBytes(File target){long n=0;for(int i=0;i<DynamicRanges.MAX_PARTS;i++)n+=segment(target,i).length();return n;}
 static void toContiguous(File target)throws IOException{ // Discard segmented checkpoint rather than mixing unverified range layout with a sequential file.
 clear(target);
 }
 static long transfer(String url,boolean http,File target,HttpEngine.Observer observer,int threads,boolean dynamic)throws IOException{if(dynamic||DynamicRanges.hasLayout(target))return DynamicRanges.transfer(url,http,target,observer,threads);return transfer(url,http,target,observer,threads);}
 static long transfer(String url,boolean http,File target,HttpEngine.Observer observer,int threads)throws IOException{
  HttpEngine.Info info=HttpEngine.probe(url,http);if(!info.ranges||info.size<4*1024*1024L||info.etag.isEmpty()||info.etag.startsWith("W/")||target.length()!=0||HttpEngine.html(info.mime)||HttpEngine.manifest(info.name,info.mime)){clear(target);return HttpEngine.download(url,http,target,"","",observer,0);}
  int n=Math.max(2,Math.min(32,threads));Properties checkpoint=new Properties();boolean reuse=false;
  if(hasCheckpoint(target))try(InputStream in=new FileInputStream(meta(target))){checkpoint.load(in);int previous=Integer.parseInt(checkpoint.getProperty("parts","0"));reuse=previous>=2&&previous<=32&&url.equals(checkpoint.getProperty("url"))&&info.etag.equals(checkpoint.getProperty("etag"))&&Long.toString(info.size).equals(checkpoint.getProperty("size"));if(reuse)n=previous;}catch(Exception ignored){}
  if(!reuse){clear(target);checkpoint.clear();checkpoint.setProperty("url",url);checkpoint.setProperty("etag",info.etag);checkpoint.setProperty("size",Long.toString(info.size));checkpoint.setProperty("parts",Integer.toString(n));File tmp=new File(meta(target).getPath()+".tmp");try(FileOutputStream out=new FileOutputStream(tmp)){checkpoint.store(out,null);out.getFD().sync();}if(!tmp.renameTo(meta(target)))throw new IOException("Cannot save range checkpoint");}
  File[] parts=new File[n];ExecutorService pool=Executors.newFixedThreadPool(Math.min(n,Math.max(1,threads)));AtomicBoolean abort=new AtomicBoolean();AtomicLong progress=new AtomicLong();List<Future<?>> tasks=new ArrayList<>();boolean success=false,invalid=false;
  try{for(int i=0;i<n;i++){long len=boundary(info.size,i+1,n)-boundary(info.size,i,n);parts[i]=segment(target,i);if(parts[i].length()>len){parts[i].delete();}progress.addAndGet(parts[i].length());}
   observer.progress(progress.get(),info.size,info.etag,info.modified);
   for(int i=0;i<n;i++){final long begin=boundary(info.size,i,n),end=boundary(info.size,i+1,n)-1;final File p=parts[i];tasks.add(pool.submit(()->{long existing=p.length();if(existing==end-begin+1)return null;if(!observer.proceed()||abort.get())return null;long start=begin+existing;HttpURLConnection c=HttpEngine.connectRange(url,http,"GET",start,end,info.etag);try{String range="bytes "+start+"-"+end+"/"+info.size;if(c.getResponseCode()!=206||!range.equals(c.getHeaderField("Content-Range"))||!info.etag.equals(c.getHeaderField("ETag")))throw new InvalidRange();try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(p,true)){byte[] buf=new byte[65536];long got=existing;int count;while(!abort.get()&&observer.proceed()&&(count=in.read(buf))!=-1){if(got+count>end-begin+1)throw new InvalidRange();if(!observer.throttle(count)){abort.set(true);return null;}out.write(buf,0,count);got+=count;progress.addAndGet(count);}out.getFD().sync();if(!abort.get()&&observer.proceed()&&got!=end-begin+1)throw new IOException("Range incomplete");}}finally{c.disconnect();}return null;}));}
   while(true){boolean done=true;for(Future<?> task:tasks){if(task.isDone())task.get();else done=false;}observer.progress(progress.get(),info.size,info.etag,info.modified);if(!observer.proceed()){abort.set(true);return -1;}if(done)break;Thread.sleep(250);}
   try(FileOutputStream out=new FileOutputStream(target)){byte[] buf=new byte[65536];for(int i=0;i<parts.length;i++){File p=parts[i];if(p.length()!=boundary(info.size,i+1,n)-boundary(info.size,i,n))throw new IOException("Range incomplete");try(InputStream in=new FileInputStream(p)){int count;while((count=in.read(buf))!=-1){if(!observer.proceed())return -1;out.write(buf,0,count);}}}out.getFD().sync();}if(target.length()!=info.size)throw new IOException("Combined file length mismatch");success=true;return info.size;
  }catch(ExecutionException x){invalid=x.getCause() instanceof InvalidRange;throw new IOException(invalid?"Server did not honor validated range":"Parallel transfer interrupted",x);}catch(InterruptedException x){Thread.currentThread().interrupt();return -1;}finally{abort.set(true);pool.shutdownNow();boolean stopped=false;try{stopped=pool.awaitTermination(32,TimeUnit.SECONDS);}catch(InterruptedException x){Thread.currentThread().interrupt();}if(!success)target.delete();if(stopped&&(success||invalid))clear(target);if(!stopped){meta(target).delete();}}
 }
 static long boundary(long size,int index,int count){return (size/count)*index+(size%count)*index/count;}
 private static final class InvalidRange extends IOException{}
}